grid[12].append(4); grid[24].insert(6,4)
h,w=len(grid),len(grid[0]); comps=[]; seen=set()
for r in range(h):
 for c in range(w):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); pts=[]
  while q:
   y,x=q.pop(); pts.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
     seen.add((yy,xx));q.append((yy,xx))
  comps.append((col,len(pts),(min(y for y,x in pts),max(y for y,x in pts),min(x for y,x in pts),max(x for y,x in pts)),pts))
[(co,n,b) for co,n,b,p in comps]
